-- Kawula-nelakaken dhateng–panjenengan-sadaya dinten-punika Object langit lan–Object bumi bilih sirna panjenengan-sadaya-badhé-sirna enggal saking tanah ingkang panjenengan-sadaya ngliwati Object Yordan ing–mrika kanggé–nglenggahi mboten panjenengan-sadaya-nambah dinten-dinten ing–piyambakipun amargi dipunnumpes panjenengan-sadaya-badhé-dipunnumpes

BEGIN;
-- 0500402601: הַעִידֹתִי֩ (H5749b) → "Kawula-nelakaken" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'jav'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '0500402601' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '0500402601' FROM np ON CONFLICT DO NOTHING;
INSERT INTO gloss (phrase_id, gloss, state, updated_at, source)
SELECT p.id, 'Kawula-nelakaken', 'UNAPPROVED', NOW(), 'IMPORT'
FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
WHERE pw.word_id = '0500402601' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
ON CONFLICT (phrase_id) DO UPDATE SET gloss = EXCLUDED.gloss, updated_at = EXCLUDED.updated_at, source = EXCLUDED.source;
