-- Lan–panjenengan–mangertos dinten–punika bilih Yéhuwah Gusti-Allah-panjenengan Panjenenganipun ingkang–nyabrang wonten–ing–ngajeng-panjenengan latu ingkang–nglebur Panjenenganipun badhé–numpes–piyambakipun lan–Panjenenganipun badhé–ngandhapaken–piyambakipun wonten–ing–ngarsaning-panjenengan lan–panjenengan–nundhung–piyambakipun lan–panjenengan–numpes–piyambakipun enggal kados–déné ngendika Yéhuwah dhateng–panjenengan

BEGIN;
-- 0500900301: וְיָדַעְתָּ֣ (H3045) → "Lan–panjenengan–mangertos" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'jav'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '0500900301' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '0500900301' FROM np ON CONFLICT DO NOTHING;
INSERT INTO gloss (phrase_id, gloss, state, updated_at, source)
SELECT p.id, 'Lan–panjenengan–mangertos', 'UNAPPROVED', NOW(), 'IMPORT'
FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
WHERE pw.word_id = '0500900301' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
ON CONFLICT (phrase_id) DO UPDATE SET gloss = EXCLUDED.gloss, updated_at = EXCLUDED.updated_at, source = EXCLUDED.source;
