-- Lan–mendhet saking–wiwitan sedaya– wowohan tanah–punika ingkang panjenengan–beta saking–tanah–panjenengan ingkang Yéhuwah Gusti–Allah–panjenengan paring dhateng–panjenengan lan–ndelehaken ing–kranjang lan–tindak dhateng– panggenan–punika ingkang dipunpilih Yéhuwah Gusti–Allah–panjenengan kanggé–ndelehaken asmanipun wonten–mrika

BEGIN;
-- 0502600201: וְלָקַחְתָּ֞ (H3947) → "Lan–mendhet" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'jav'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '0502600201' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '0502600201' FROM np ON CONFLICT DO NOTHING;
INSERT INTO gloss (phrase_id, gloss, state, updated_at, source)
SELECT p.id, 'Lan–mendhet', 'UNAPPROVED', NOW(), 'IMPORT'
FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
WHERE pw.word_id = '0502600201' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
ON CONFLICT (phrase_id) DO UPDATE SET gloss = EXCLUDED.gloss, updated_at = EXCLUDED.updated_at, source = EXCLUDED.source;
